import React from "react";


const Home = () => {
  return (
    <header
      className="header"
      style={{ backgroundImage: "url(/img/header-bg.png)", 
        textAlign: "center",
      }}
    >
      <div className="header-content">
        <h1 className="header-title">
          Hi, my name is <strong>Asan</strong>
        </h1>
        <p className="header-text">Frontend developer</p>
      </div>
    </header>
  );
};

export default Home;
